namespace App\Http\Resources;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class MarketplaceOrderResource extends JsonResource
{
    public function toArray(Request $request): array
    {
        $isPlatformAdmin = $request->user()?->can('viewFinances', $this->resource);

        return [
            'order_id' => $this->id,
            'product_name' => $this->item->name,
            'retail_price' => $this->retail_amount,
            'supplier_cost' => $this->when($isPlatformAdmin, $this->wholesale_cost),
            'platform_commission_pct' => $this->when($isPlatformAdmin, $this->vendor->commission_rate),
            'vendor_tax_id' => $this->when($isPlatformAdmin, $this->vendor->ein_number)
        ];
    }
}
